import java.util.*;

class Solution {
    public void flatten(TreeNode root) {
        List<TreeNode> list = new ArrayList<>();
        preorder(root, list);

        for (int i = 0; i < list.size() - 1; i++) {
            TreeNode node = list.get(i);
            node.left = null;              // 必须置空，否则成环
            node.right = list.get(i + 1);
        }
        if (!list.isEmpty()) {
            TreeNode last = list.get(list.size() - 1);
            last.left = null;
            last.right = null;
        }
    }

    private void preorder(TreeNode node, List<TreeNode> list) {
        if (node == null) return;
        list.add(node);
        preorder(node.left, list);
        preorder(node.right, list);
    }
}

class Solution {
    public void flatten(TreeNode root) {
        if (root != null) flattenTree(root);
    }

    // 返回本子树展开成链之后的尾节点
    private TreeNode flattenTree(TreeNode node) {
        if (node == null) return null;

        TreeNode leftTail = flattenTree(node.left);
        TreeNode rightTail = flattenTree(node.right);

        TreeNode left = node.left;
        TreeNode right = node.right;

        if (left != null) {
            node.left = null;
            node.right = left;
            leftTail.right = right;   // 右子树接到左链尾部
        }

        if (rightTail != null) return rightTail;
        if (leftTail != null) return leftTail;
        return node;
    }
}

class Solution {
    public void flatten(TreeNode root) {
        TreeNode cur = root;
        while (cur != null) {
            if (cur.left == null) {
                cur = cur.right;      // 只有右链，直接前进
                continue;
            }
            // 找左子树的最右节点，它就是接缝
            TreeNode pre = cur.left;
            while (pre.right != null) pre = pre.right;

            pre.right = cur.right;    // 右子树整段挂到接缝后面
            cur.right = cur.left;     // 左子树插队到右边
            cur.left = null;          // 必须置空，否则成环

            cur = cur.right;
        }
    }
}
